const PAGE_SIZE = 25;

export async function listOrders(db: Db, merchantId: string, page: number): Promise<Page<Order>> {
  if (!Number.isInteger(page) || page < 1) {
    throw new BadRequestError("page must be a positive integer");
  }
  const offset = page * PAGE_SIZE; //!issue:1
  const [rows, total] = await Promise.all([
    db.query<Order>(
      "SELECT * FROM orders WHERE merchant_id = $1 ORDER BY created_at DESC LIMIT $2 OFFSET $3",
      [merchantId, PAGE_SIZE, offset],
    ),
    db.count("orders", { merchant_id: merchantId }),
  ]);
  return { items: rows, page, totalPages: Math.ceil(total / PAGE_SIZE) };
}

