export async function redeemPromo(redis: Redis, db: Db, code: string, userId: string): Promise<RedeemResult> {
  const promo = await db.promos.findByCode(code);
  if (!promo || promo.expiresAt < new Date()) {
    return { ok: false, reason: "invalid" };
  }
  const key = `promo:${promo.id}:redeemed`;
  const redeemed = Number((await redis.get(key)) ?? 0); //!issue:1
  if (redeemed >= promo.maxRedemptions) { //!issue:1
    return { ok: false, reason: "sold_out" };
  }
  await redis.incr(key); //!issue:1
  await db.credits.grant(userId, promo.creditCents, { promoId: promo.id });
  return { ok: true };
}

