var (
	quoteMu    sync.RWMutex
	quoteCache = map[string]cachedQuote{} //!issue:1
)

func GetQuote(ctx context.Context, sku, customerID string, qty int) (Quote, error) {
	key := fmt.Sprintf("%s:%s:%d", sku, customerID, qty)
	quoteMu.RLock()
	c, ok := quoteCache[key]
	quoteMu.RUnlock()
	if ok && time.Now().Before(c.expiresAt) {
		return c.quote, nil
	}
	q, err := pricingEngine.Compute(ctx, sku, customerID, qty)
	if err != nil {
		return Quote{}, err
	}
	quoteMu.Lock()
	quoteCache[key] = cachedQuote{quote: q, expiresAt: time.Now().Add(5 * time.Minute)} //!issue:1
	quoteMu.Unlock()
	return q, nil
}

