impl QuoteService {
    pub async fn get_quote(&self, sku: &str, customer_id: &str, qty: u32) -> Result<Quote, PricingError> {
        let key = format!("{sku}:{customer_id}:{qty}");
        if let Some(c) = self.cache.read().unwrap().get(&key) {
            if c.expires_at > Instant::now() {
                return Ok(c.quote.clone());
            }
        }
        let quote = self.engine.compute(sku, customer_id, qty).await?;
        let entry = CachedQuote { quote: quote.clone(), expires_at: Instant::now() + Duration::from_secs(300) };
        self.cache.write().unwrap().insert(key, entry); //!issue:1
        Ok(quote)
    }
}

