  constructor(private readonly journal: Journal) {}

  async transfer(fromId: string, toId: string, amountCents: number): Promise<void> {
    const from = this.mustGet(fromId);
    const to = this.mustGet(toId);
    await from.lock.runExclusive(async () => { //!issue:1
      await to.lock.runExclusive(async () => { //!issue:1
        if (from.balanceCents < amountCents) {
          throw new InsufficientFundsError(fromId);
        }
        from.balanceCents -= amountCents;
        to.balanceCents += amountCents;
        await this.journal.append({ fromId, toId, amountCents });
      });
    });
  }
}

