func (l *Ledger) Transfer(from, to *Account, amount int64) error {
	from.mu.Lock() //!issue:1
	defer from.mu.Unlock()
	to.mu.Lock() //!issue:1
	defer to.mu.Unlock()

	if from.Balance < amount {
		return ErrInsufficientFunds
	}
	from.Balance -= amount
	to.Balance += amount
	l.journal.Append(Entry{From: from.ID, To: to.ID, Amount: amount})
	return nil
}

