    // Shared with the periodic flush timer, hence Arc<Mutex<..>>.
    let buffer: Arc<Mutex<Vec<Event>>> = Arc::new(Mutex::new(Vec::with_capacity(BATCH_SIZE)));
    let permits = Arc::new(Semaphore::new(4)); // at most 4 concurrent warehouse writes
    let mut tasks = JoinSet::new();
    while let Some(event) = events.recv().await {
        let mut buf = buffer.lock().await;
        buf.push(event);
        if buf.len() >= BATCH_SIZE {
            let permit = permits.clone().acquire_owned().await?;
            let (sink, shared) = (sink.clone(), buffer.clone()); //!issue:1
            tasks.spawn(async move {
                let batch = shared.lock().await; //!issue:1
                let result = sink.write(&batch).await;
                drop(permit);
                result
            });
            buf.clear(); //!issue:1
        }
    }
    while let Some(res) = tasks.join_next().await {
        res??;
    }
    Ok(())
